{"command": "create", "path": "<local-workspace>", "summary": "Create main lab HTML file", "file_text": "<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8" />
<meta name="viewport" content="width=device-width, initial-scale=1, maximum-scale=1, user-scalable=no" />
<title>Virtual Spread Plate Lab</title>
<style>
  :root {
    --bg: #0f1620;
    --panel: #1b2632;
    --panel-2: #243140;
    --ink: #eaf2fb;
    --muted: #93a4b6;
    --accent: #4fd0e0;
    --accent-2: #ffb454;
    --good: #6ee0a0;
    --warn: #ff6b6b;
    --bench: #d8c9a3;
    --bench-edge: #b6a67f;
  }
  * { box-sizing: border-box; }
  html, body { margin: 0; padding: 0; height: 100%; }
  body {
    font-family: system-ui, -apple-system, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
    color: var(--ink);
    background:
      radial-gradient(1200px 700px at 80% -10%, #1f2e3d 0%, rgba(31,46,61,0) 60%),
      radial-gradient(900px 600px at 0% 110%, #1a2b3a 0%, rgba(26,43,58,0) 55%),
      var(--bg);
    -webkit-text-size-adjust: 100%;
  }
  .app {
    max-width: 1080px;
    margin: 0 auto;
    padding: 14px 14px 30px;
  }
  header.top {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 10px;
    padding: 6px 2px 12px;
    flex-wrap: wrap;
  }
  header.top h1 {
    font-size: clamp(18px, 4.6vw, 26px);
    margin: 0;
    letter-spacing: 0.3px;
    background: linear-gradient(90deg, var(--accent), var(--accent-2));
    -webkit-background-clip: text;
    background-clip: text;
    color: transparent;
  }
  .subtitle { color: var(--muted); font-size: 13px; margin-top: 2px; }

  .grid {
    display: grid;
    grid-template-columns: 1fr 320px;
    gap: 14px;
    align-items: start;
  }
  @media (max-width: 880px) {
    .grid { grid-template-columns: 1fr; }
  }

  /* Lab stage */
  .stage {
    position: relative;
    background: var(--panel);
    border: 1px solid #2f4150;
    border-radius: 16px;
    overflow: hidden;
    box-shadow: 0 10px 30px rgba(0,0,0,0.35);
  }
  .scene {
    position: relative;
    width: 100%;
    aspect-ratio: 16 / 11;
    min-height: 340px;
    user-select: none;
    touch-action: none;
  }
  .scene svg { position: absolute; inset: 0; width: 100%; height: 100%; display: block; }

  /* draggable equipment */
  .equip {
    position: absolute;
    cursor: grab;
    z-index: 5;
    transition: transform 0.08s ease;
    will-change: transform;
    -webkit-user-drag: none;
  }
  .equip.dragging { cursor: grabbing; z-index: 20; }
  .equip svg { display: block; width: 100%; height: 100%; pointer-events: none; }
  .equip .lbl {
    position: absolute;
    bottom: -16px;
    left: 50%;
    transform: translateX(-50%);
    font-size: 10px;
    color: var(--muted);
    white-space: nowrap;
    pointer-events: none;
  }
  .equip.near-flame { filter: drop-shadow(0 0 6px rgba(255,180,80,0.9)); }

  /* Side panels (equipment trays) */
  .tray {
    position: absolute;
    top: 0;
    bottom: 0;
    width: 22%;
    min-width: 92px;
    z-index: 2;
    pointer-events: none;
  }
  .tray.left { left: 0; }
  .tray.right { right: 0; }
  .tray::before {
    content: "";
    position: absolute;
    inset: 6% 0;
    background: linear-gradient(180deg, rgba(0,0,0,0.18), rgba(0,0,0,0.05));
    border-radius: 0 12px 12px 0;
  }
  .tray.right::before {
    border-radius: 12px 0 0 12px;
  }
  .tray-label {
    position: absolute;
    top: 8px;
    left: 50%;
    transform: translateX(-50%);
    font-size: 10px;
    color: var(--muted);
    letter-spacing: 0.08em;
    text-transform: uppercase;
    pointer-events: none;
  }

  /* Clean bench / work area visual */
  .bench-rect { pointer-events: none; }

  /* Overlays: growth, smear */
  .growth-layer, .smear-layer { pointer-events: none; }

  /* Controls side */
  .controls {
    display: flex;
    flex-direction: column;
    gap: 12px;
  }
  .card {
    background: var(--panel);
    border: 1px solid #2f4150;
    border-radius: 14px;
    padding: 14px;
  }
  .step-card .step-num {
    font-size: 11px;
    color: var(--accent);
    letter-spacing: 0.14em;
    text-transform: uppercase;
  }
  .step-card h2 {
    margin: 4px 0 8px;
    font-size: clamp(16px, 3.6vw, 20px);
  }
  [data-testid="step-instruction"] {
    font-size: 14px;
    line-height: 1.45;
    color: #cfe0ee;
    min-height: 2.6em;
  }
  .feedback {
    margin-top: 10px;
    min-height: 1.6em;
    font-size: 13px;
    border-radius: 10px;
    padding: 8px 10px;
    border: 1px solid transparent;
    transition: background 0.2s, border-color 0.2s;
  }
  .feedback.info { background: rgba(79,208,224,0.08); border-color: rgba(79,208,224,0.35); color: #bdeef6; }
  .feedback.ok { background: rgba(110,224,160,0.10); border-color: rgba(110,224,160,0.40); color: #d6f7e3; }
  .feedback.err { background: rgba(255,107,107,0.10); border-color: rgba(255,107,107,0.40); color: #ffd9d9; }

  .actions {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 8px;
  }
  .actions button { grid-column: span 2; }
  @media (min-width: 560px) { .actions button { grid-column: auto; } }

  button.act {
    appearance: none;
    border: 1px solid #34505f;
    background: linear-gradient(180deg, #283a4a, #1f2e3c);
    color: var(--ink);
    font-size: 14px;
    font-weight: 600;
    padding: 10px 12px;
    border-radius: 10px;
    cursor: pointer;
    transition: transform 0.05s, border-color 0.15s, background 0.15s, opacity 0.15s;
  }
  button.act:hover { border-color: var(--accent); }
  button.act:active { transform: translateY(1px); }
  button.act[disabled] { opacity: 0.45; cursor: not-allowed; }
  button.act.is-current {
    border-color: var(--accent);
    box-shadow: 0 0 0 1px rgba(79,208,224,0.35), 0 6px 18px rgba(79,208,224,0.15);
  }
  button.reset {
    border-color: #5a3a3a;
    background: linear-gradient(180deg, #3a2424, #2a1a1a);
    color: #ffd9d9;
  }
  button.reset:hover { border-color: var(--warn); }

  .progress {
    display: flex;
    gap: 6px;
    flex-wrap: wrap;
  }
  .progress .dot {
    flex: 1 1 0;
    min-width: 18px;
    height: 8px;
    border-radius: 999px;
    background: #2a3a47;
    transition: background 0.2s;
  }
  .progress .dot.done { background: var(--good); }
  .progress .dot.active { background: var(--accent); }
  .progress-label { font-size: 11px; color: var(--muted); margin-top: 6px; }

  .microscope, .quiz {
    background: var(--panel-2);
    border: 1px solid #34505f;
    border-radius: 12px;
    padding: 12px;
  }
  .microscope h3, .quiz h3 { margin: 0 0 8px; font-size: 14px; color: var(--accent); }
  .scope-eye {
    width: 100%;
    aspect-ratio: 1 / 1;
    border-radius: 50%;
    background: radial-gradient(circle at 50% 45%, #f4f1e8 0%, #e3dbc4 55%, #b9ad8c 100%);
    border: 4px solid #2a3a47;
    position: relative;
    overflow: hidden;
    box-shadow: inset 0 0 24px rgba(0,0,0,0.25);
  }
  .scope-eye .colonies { position: absolute; inset: 0; }
  .scope-eye .colonies circle { fill: #f3efe1; stroke: #c9bb98; stroke-width: 0.5; }
  .scope-empty { position: absolute; inset: 0; display: grid; place-items: center; color: #8a7d5e; font-size: 12px; text-align: center; padding: 10px; }

  .quiz q { display: block; font-size: 13px; margin-bottom: 8px; color: #d6e6f3; }
  .quiz .opts { display: grid; gap: 6px; }
  .quiz .opts button {
    appearance: none;
    border: 1px solid #34505f;
    background: #1f2e3c;
    color: var(--ink);
    border-radius: 8px;
    padding: 8px;
    font-size: 13px;
    cursor: pointer;
    text-align: left;
  }
  .quiz .opts button:hover { border-color: var(--accent); }
  .quiz .opts button.correct { border-color: var(--good); color: #d6f7e3; }
  .quiz .opts button.wrong { border-color: var(--warn); color: #ffd9d9; }
  .quiz .qresult { font-size: 12px; margin-top: 6px; color: var(--muted); }

  .warn-strip {
    display: flex;
    align-items: center;
    gap: 8px;
    background: linear-gradient(90deg, #3a1414, #2a1a1a);
    border: 1px solid #6a2222;
    border-radius: 10px;
    padding: 8px 10px;
    font-size: 12px;
    color: #ffd9d9;
  }
  .warn-strip .icon {
    width: 18px; height: 18px; border-radius: 50%;
    background: radial-gradient(circle, #ffcf5f, #e07020);
    display: grid; place-items: center;
    color: #2a1a1a; font-weight: 800; font-size: 13px;
    flex: 0 0 auto;
  }
  .footer-note { font-size: 11px; color: var(--muted); margin-top: 14px; line-height: 1.5; }
  .kbd { font-family: ui-monospace, monospace; background: #16222e; padding: 1px 5px; border-radius: 4px; }
</style>
</head>
<body>
<div class="app" data-testid="lab-root" data-step="sterilize" id="labRoot">

  <header class="top">
    <div>
      <h1>Virtual Spread Plate Lab</h1>
      <div class="subtitle">Microbiology · Spread-plate technique · Yeast culture on agar</div>
    </div>
    <div class="warn-strip" title="Flammable">
      <span class="icon">!</span>
      <span>Flammable: alcohol lamp + open flame. Keep away from alcohol sprays &amp; paper.</span>
    </div>
  </header>

  <div class="grid">
    <!-- LAB STAGE -->
    <div class="stage">
      <div class="scene" id="scene">

        <!-- background art: lab bench + sterile zone -->
        <svg viewBox="0 0 800 550" preserveAspectRatio="none" aria-hidden="true">
          <defs>
            <linearGradient id="benchGrad" x1="0" y1="0" x2="0" y2="1">
              <stop offset="0" stop-color="#cdbb92"/>
              <stop offset="1" stop-color="#b6a479"/>
            </linearGradient>
            <radialGradient id="sterileGlow" cx="0.5" cy="0.55" r="0.6">
              <stop offset="0" stop-color="rgba(120,220,255,0.10)"/>
              <stop offset="1" stop-color="rgba(120,220,255,0)"/>
            </radialGradient>
            <linearGradient id="bgGrad" x1="0" y1="0" x2="0" y2="1">
              <stop offset="0" stop-color="#15212c"/>
              <stop offset="1" stop-color="#101a24"/>
            </linearGradient>
          </defs>
          <rect x="0" y="0" width="800" height="550" fill="url(#bgGrad)"/>
          <!-- back wall tiles -->
          <g opacity="0.18" stroke="#2a3a47" stroke-width="1">
            <line x1="0" y1="60" x2="800" y2="60"/>
            <line x1="0" y1="120" x2="800" y2="120"/>
            <line x1="0" y1="180" x2="800" y2="180"/>
          </g>
          <!-- bench surface -->
          <rect class="bench-rect" data-testid="equipment-clean-bench" draggable="true"
                x="40" y="180" width="720" height="330" rx="22"
                fill="url(#benchGrad)" stroke="#9c8b62" stroke-width="2"/>
          <!-- sterile work zone highlight -->
          <rect x="180" y="220" width="440" height="250" rx="16"
                fill="url(#sterileGlow)" stroke="rgba(120,220,255,0.35)" stroke-width="1.5" stroke-dasharray="6 6"/>
          <text x="400" y="214" text-anchor="middle" font-size="12" fill="#9fe" opacity="0.7">Sterile work area</text>

          <!-- agar plate art (static plate base under draggable) -->
          <g id="plateBase" transform="translate(400,360)">
            <ellipse cx="0" cy="6" rx="96" ry="26" fill="rgba(0,0,0,0.22)"/>
            <ellipse cx="0" cy="0" rx="96" ry="26" fill="#e9eef0" stroke="#c4ccd0" stroke-width="2"/>
            <ellipse cx="0" cy="-2" rx="86" ry="22" fill="#9bd6a8" stroke="#79bd8e" stroke-width="1.5"/>
            <ellipse cx="0" cy="-3" rx="80" ry="19" fill="#8acda0"/>
          </g>

          <!-- spread smear (drawn as steps progress) -->
          <g id="smearLayer" class="smear-layer" transform="translate(400,358)"></g>
          <!-- growth colonies -->
          <g id="growthLayer" class="growth-layer" transform="translate(400,358)"></g>
        </svg>

        <!-- LEFT tray label -->
        <div class="tray left">
          <span class="tray-label">Tray A</span>
        </div>
        <div class="tray right">
          <span class="tray-label">Tray B</span>
        </div>

        <!-- equipment (draggable) -->
        <!-- Alcohol lamp -->
        <div class="equip" data-testid="equipment-alcohol-lamp" draggable="true" id="lamp"
             style="left: 3%; top: 40%; width: 8%; min-width: 46px; aspect-ratio: 1/1.5;">
          <svg viewBox="0 0 60 90">
            <defs>
              <linearGradient id="lampBody" x1="0" y1="0" x2="1" y2="0">
                <stop offset="0" stop-color="#5a6b7a"/><stop offset="0.5" stop-color="#c9d6e0"/><stop offset="1" stop-color="#5a6b7a"/>
              </linearGradient>
              <radialGradient id="flame" cx="0.5" cy="0.7" r="0.7">
                <stop offset="0" stop-color="#fff7c2"/><stop offset="0.4" stop-color="#ffd24c"/><stop offset="0.8" stop-color="#ff7a1a"/><stop offset="1" stop-color="rgba(255,90,20,0)"/>
              </radialGradient>
            </defs>
            <rect x="14" y="40" width="32" height="44" rx="6" fill="url(#lampBody)" stroke="#3a4754" stroke-width="1"/>
            <rect x="20" y="30" width="20" height="12" rx="3" fill="#8b97a3" stroke="#566472"/>
            <rect x="26" y="22" width="8" height="10" fill="#d8d8d8"/>
            <ellipse cx="30" cy="14" rx="7" ry="11" fill="url(#flame)" class="flame" id="lampFlame"/>
            <ellipse cx="30" cy="20" rx="2.4" ry="4" fill="#7fb8ff" opacity="0.85"/>
          </svg>
          <span class="lbl">Alcohol lamp</span>
        </div>

        <!-- Inoculation loop -->
        <div class="equip" data-testid="equipment-inoculation-loop" draggable="true" id="loop"
             style="left: 13%; top: 24%; width: 13%; min-width: 70px; aspect-ratio: 2/1;">
          <svg viewBox="0 0 120 60">
            <line x1="6" y1="30" x2="74" y2="30" stroke="#7a5a3a" stroke-width="5" stroke-linecap="round"/>
            <line x1="6" y1="30" x2="74" y2="30" stroke="#b08a5c" stroke-width="2"/>
            <circle id="loopRing" cx="92" cy="30" r="14" fill="none" stroke="#cfd8df" stroke-width="3.2"/>
            <circle id="loopRingTip" cx="92" cy="30" r="3" fill="#ffd24c" opacity="0"/>
          </svg>
          <span class="lbl">Inoculation loop</span>
        </div>

        <!-- Yeast broth test tube -->
        <div class="equip" data-testid="equipment-yeast-broth" draggable="true" id="broth"
             style="left: 80%; top: 18%; width: 7%; min-width: 40px; aspect-ratio: 1/2.6;">
          <svg viewBox="0 0 40 104">
            <defs>
              <linearGradient id="glass" x1="0" y1="0" x2="1" y2="0">
                <stop offset="0" stop-color="rgba(255,255,255,0.6)"/><stop offset="0.5" stop-color="rgba(220,235,245,0.15)"/><stop offset="1" stop-color="rgba(255,255,255,0.6)"/>
              </linearGradient>
            </defs>
            <rect x="11" y="8" width="18" height="86" rx="9" fill="rgba(230,240,250,0.25)" stroke="#bcd" stroke-width="1.2"/>
            <rect x="12" y="40" width="16" height="52" rx="8" fill="#d9b25a"/>
            <rect x="12" y="40" width="16" height="10" rx="4" fill="#e8c878"/>
            <rect x="12" y="8" width="16" height="86" rx="8" fill="url(#glass)"/>
            <ellipse cx="20" cy="40" rx="8" ry="3" fill="#caa14e"/>
            <!-- cotton plug on top -->
            <ellipse cx="20" cy="6" rx="12" ry="6" fill="#f3efe6" stroke="#d8cfc0" stroke-width="1"/>
            <path d="M8 6 Q20 -2 32 6" fill="none" stroke="#d8cfc0" stroke-width="1"/>
          </svg>
          <span class="lbl">Yeast broth</span>
        </div>

        <!-- Cotton plug (separate) -->
        <div class="equip" data-testid="equipment-cotton-plug" draggable="true" id="cotton"
             style="left: 88%; top: 30%; width: 6%; min-width: 36px; aspect-ratio: 1/1;">
          <svg viewBox="0 0 48 48">
            <ellipse cx="24" cy="26" rx="16" ry="14" fill="#f3efe6" stroke="#d8cfc0" stroke-width="1.2"/>
            <ellipse cx="20" cy="22" rx="6" ry="4" fill="#fff" opacity="0.7"/>
            <ellipse cx="30" cy="28" rx="5" ry="3" fill="#e7dfd0" opacity="0.7"/>
          </svg>
          <span class="lbl">Cotton plug</span>
        </div>

        <!-- Agar plate (draggable lid) -->
        <div class="equip" data-testid="equipment-agar-plate" draggable="true" id="plate"
             style="left: 41%; top: 58%; width: 18%; min-width: 120px; aspect-ratio: 2.4/1;">
          <svg viewBox="0 0 200 84">
            <ellipse cx="100" cy="44" rx="92" ry="26" fill="rgba(0,0,0,0.18)"/>
            <ellipse cx="100" cy="40" rx="92" ry="26" fill="#f1f5f6" stroke="#c4ccd0" stroke-width="2.5"/>
            <ellipse cx="100" cy="38" rx="84" ry="22" fill="#9bd6a8" stroke="#79bd8e" stroke-width="1.5"/>
            <ellipse id="plateSample" cx="100" cy="38" rx="6" ry="3" fill="#e8c878" opacity="0"/>
            <ellipse id="plateSpread" cx="100" cy="38" rx="80" ry="20" fill="#8acda0" opacity="0"/>
          </svg>
          <span class="lbl">Agar plate</span>
        </div>

      </div>
    </div>

    <!-- CONTROLS -->
    <div class="controls">
      <div class="card step-card">
        <div class="step-num" id="stepNum">Step 1 of 6</div>
        <h2 id="stepTitle">Sterilize the loop</h2>
        <div data-testid="step-instruction" id="stepInstruction">
          Drag the inoculation loop to the alcohol lamp flame, then press <b>Sterilize</b> to flame-sterilize it.
        </div>
        <div class="feedback info" data-testid="feedback" id="feedback">Welcome! Begin by sterilizing your inoculation loop.</div>

        <div class="actions" style="margin-top:12px">
          <button class="act" data-action="sterilize" id="btn-sterilize">🔥 Sterilize</button>
          <button class="act" data-action="cool" id="btn-cool">❄️ Cool loop</button>
          <button class="act" data-action="sample" id="btn-sample">🧫 Sample culture</button>
          <button class="act" data-action="inoculate" id="btn-inoculate">💧 Inoculate plate</button>
          <button class="act" data-action="spread" id="btn-spread">↪ Spread sample</button>
          <button class="act" data-action="incubate" id="btn-incubate">🌡️ Incubate</button>
          <button class="act reset" data-action="reset" id="btn-reset">↺ Reset</button>
        </div>
      </div>

      <div class="card">
        <div data-testid="progress" id="progress" class="progress" aria-label="Progress"></div>
        <div class="progress-label" id="progressLabel">0 / 6 steps complete</div>
      </div>

      <div class="microscope">
        <h3>🔬 Microscope view</h3>
        <div class="scope-eye" id="scopeEye">
          <svg class="colonies" viewBox="0 0 100 100" id="scopeColonies"></svg>
          <div class="scope-empty" id="scopeEmpty">Nothing to view yet. After incubation, colonies appear here.</div>
        </div>
      </div>

      <div class="quiz" id="quiz">
        <h3>✅ Quick check</h3>
        <q id="quizQ">Why must you flame-sterilize the loop <i>before</i> sampling?</q>
        <div class="opts" id="quizOpts"></div>
        <div class="qresult" id="quizResult"></div>
      </div>
    </div>
  </div>

  <p class="footer-note">
    Drag equipment with your mouse or finger. Buttons are also wired to the public <span class="kbd">window.spreadPlateLab</span> API —
    open the console and try <span class="kbd">spreadPlateLab.getState()</span>, <span class="kbd">spreadPlateLab.perform('cool')</span>.
    Repeated clicks are safe; invalid actions keep you on the current step and explain what to do next.
  </p>
</div>

<script>
"use strict";
(function () {
  const STEPS = ["sterilize", "cool", "sample", "inoculate", "spread", "incubate", "complete"];

  const STEP_META = {
    sterilize:  { n: 1, title: "Sterilize the loop",    why: "Flaming kills microbes on the wire so you don't contaminate your sample." },
    cool:       { n: 2, title: "Cool the loop",         why: "A red-hot loop would kill the yeast you want to culture. Cool it in the sterile zone." },
    sample:     { n: 3, title: "Sample the culture",   why: "Dip the sterile loop into the yeast broth to pick up cells." },
    inoculate:  { n: 4, title: "Inoculate the plate",  why: "Transfer a drop of broth onto the agar surface." },
    spread:     { n: 5, title: "Spread the sample",     why: "Spreading dilutes cells so separate colonies can form, not a lawn." },
    incubate:   { n: 6, title: "Incubate & observe",    why: "Warmth lets yeast divide into visible colonies." },
    complete:   { n: 0, title: "Experiment complete",   why: "" }
  };

  const INSTRUCTIONS = {
    sterilize:  "Drag the inoculation loop near the alcohol lamp flame, then press Sterilize to flame it red-hot.",
    cool:       "The loop is hot! Drag it into the sterile work area (dashed zone) and press Cool loop.",
    sample:     "Drag the loop into the yeast broth test tube and press Sample culture.",
    inoculate:  "Touch the loop to the agar plate surface and press Inoculate plate.",
    spread:     "Press Spread sample to streak the droplet across the whole plate.",
    incubate:   "Press Incubate to warm the plate and watch colonies grow.",
    complete:   "🎉 Success! Observe the colonies in the microscope view. Press Reset to try again."
  };

  // ---- state ----
  let state = fresh();

  function fresh() {
    return {
      step: "sterilize",
      completed: false,
      history: [],
      flameOn: true,
      loopSterile: false,
      loopHot: false,
      loopCooled: false,
      loopLoaded: false,
      plateInoculated: false,
      plateSpread: false,
      growthShown: false
    };
  }

  // ---- DOM refs ----
  const $ = (id) => document.getElementById(id);
  const labRoot = $("labRoot");
  const stepNum = $("stepNum");
  const stepTitle = $("stepTitle");
  const stepInstruction = $("stepInstruction");
  const feedback = $("feedback");
  const progress = $("progress");
  const progressLabel = $("progressLabel");
  const scopeColonies = $("scopeColonies");
  const scopeEmpty = $("scopeEmpty");
  const lampFlame = $("lampFlame");
  const loopRing = $("loopRing");
  const loopRingTip = $("loopRingTip");
  const plateSample = $("plateSample");
  const plateSpread = $("plateSpread");

  // ---- feedback ----
  function setFeedback(msg, kind) {
    feedback.textContent = msg;
    feedback.className = "feedback " + (kind || "info");
  }

  // ---- render ----
  function render() {
    const s = state.step;
    labRoot.dataset.step = s;
    const meta = STEP_META[s] || STEP_META.complete;
    if (s === "complete") {
      stepNum.textContent = "Complete";
    } else {
      stepNum.textContent = "Step " + meta.n + " of 6";
    }
    stepTitle.textContent = meta.title;
    stepInstruction.innerHTML = INSTRUCTIONS[s] + (meta.why ? ' <span style="color:#93a4b6">— ' + meta.why + '</span>' : "");

    // button highlight
    STEPS.forEach((k) => {
      const b = $("btn-" + k);
      if (!b) return;
      b.classList.toggle("is-current", k === s);
      b.disabled = (s === "complete");
    });

    // progress dots
    progress.innerHTML = "";
    const ordered = ["sterilize","cool","sample","inoculate","spread","incubate"];
    ordered.forEach((k) => {
      const d = document.createElement("div");
      d.className = "dot";
      if (state.history.includes(k)) d.classList.add("done");
      if (k === s && s !== "complete") d.classList.add("active");
      progress.appendChild(d);
    });
    const doneCount = state.history.length;
    progressLabel.textContent = doneCount + " / 6 steps complete" + (state.completed ? " — finished!" : "");

    // visuals
    lampFlame.style.opacity = state.flameOn ? "1" : "0";
    // loop color: sterile = bright, hot = red glow, loaded = gold bead
    if (state.loopHot) {
      loopRing.setAttribute("stroke", "#ff6a3a");
      loopRingTip.setAttribute("fill", "#ff8a4a");
      loopRingTip.setAttribute("opacity", "0.9");
    } else if (state.loopSterile) {
      loopRing.setAttribute("stroke", "#e8f0f5");
      loopRingTip.setAttribute("opacity", "0");
    } else {
      loopRing.setAttribute("stroke", "#9aa6ad");
      loopRingTip.setAttribute("opacity", "0");
    }
    if (state.loopLoaded) {
      loopRingTip.setAttribute("fill", "#e8c878");
      loopRingTip.setAttribute("opacity", "0.95");
    }

    // plate sample droplet
    plateSample.setAttribute("opacity", state.plateInoculated && !state.plateSpread ? "1" : "0");
    plateSpread.setAttribute("opacity", state.plateSpread ? "0.9" : "0");

    // growth colonies + microscope
    renderGrowth();
  }

  function renderGrowth() {
    const smear = $("smearLayer");
    const growth = $("growthLayer");
    smear.innerHTML = "";
    growth.innerHTML = "";

    if (state.plateSpread) {
      // streak lines
      const ns = "http://www.w3.org/2000/svg";
      for (let i = 0; i < 9; i++) {
        const p = document.createElementNS(ns, "path");
        const y = -14 + i * 3.4;
        p.setAttribute("d", "M -70 " + y + " Q 0 " + (y + (i % 2 ? 3 : -3)) + " 70 " + y);
        p.setAttribute("stroke", "rgba(120,170,130,0.5)");
        p.setAttribute("stroke-width", "2");
        p.setAttribute("fill", "none");
        smear.appendChild(p);
      }
    }

    if (state.growthShown) {
      scopeEmpty.style.display = "none";
      const ns = "http://www.w3.org/2000/svg";
      // colonies on plate
      const pts = colonies(28, 70, 18);
      pts.forEach((pt) => {
        const c = document.createElementNS(ns, "ellipse");
        c.setAttribute("cx", pt.x);
        c.setAttribute("cy", pt.y - 2);
        c.setAttribute("rx", pt.r);
        c.setAttribute("ry", pt.r * 0.42);
        c.setAttribute("fill", "#f3efe1");
        c.setAttribute("stroke", "#c9bb98");
        c.setAttribute("stroke-width", "0.6");
        growth.appendChild(c);
      });
      // microscope view
      scopeColonies.innerHTML = "";
      const mpts = colonies(36, 44, 44, 5);
      mpts.forEach((pt) => {
        const c = document.createElementNS(ns, "circle");
        c.setAttribute("cx", pt.x);
        c.setAttribute("cy", pt.y);
        c.setAttribute("r", pt.r);
        scopeColonies.appendChild(c);
      });
    } else {
      scopeEmpty.style.display = "grid";
      scopeColonies.innerHTML = "";
    }
  }

  function colonies(count, rx, ry, baseR) {
    const out = [];
    let seed = 1337;
    const rnd = () => { seed = (seed * 9301 + 49297) % 233280; return seed / 233280; };
    for (let i = 0; i < count; i++) {
      const a = rnd() * Math.PI * 2;
      const rr = Math.sqrt(rnd()) * 0.92;
      out.push({ x: Math.cos(a) * rx * rr, y: Math.sin(a) * ry * rr, r: (baseR || 3) + rnd() * 3 });
    }
    return out;
  }

  // ---- actions ----
  function perform(action) {
    if (typeof action !== "string") {
      return { ok: false, message: "Unknown action." };
    }
    const a = action.toLowerCase();

    if (a === "reset") {
      reset();
      return { ok: true, message: "Lab reset. Start by sterilizing the loop." };
    }

    // guard: must match current step
    if (a === state.step) {
      // execute it
      return doStep(a);
    }
    // special: clicking "complete" / incubate when already complete
    if (state.completed && (a === "incubate")) {
      return { ok: false, message: "Already incubated. Press Reset to start over." };
    }
    // invalid out-of-order
    const want = STEP_META[a] ? "step " + STEP_META[a].n : a;
    return {
      ok: false,
      message: "Not yet. You're on " + STEP_META[state.step].title.toLowerCase() + ". " + INSTRUCTIONS[state.step]
    };
  }

  function doStep(a) {
    switch (a) {
      case "sterilize":
        if (!nearFlame()) {
          return { ok: false, message: "Move the inoculation loop next to the alcohol lamp flame first, then sterilize." };
        }
        state.loopSterile = true;
        state.loopHot = true;
        state.loopCooled = false;
        state.loopLoaded = false;
        advance("sterilize", "Loop is now red-hot and sterile. Let it cool before touching the culture.");
        return { ok: true, message: "Loop sterilized in the flame. It's hot — cool it next." };

      case "cool":
        if (!state.loopSterile) {
          return { ok: false, message: "Sterilize the loop first." };
        }
        if (!state.loopHot) {
          return { ok: false, message: "The loop isn't hot. Sterilize it first." };
        }
        if (!inSterileZone()) {
          return { ok: false, message: "Drag the loop into the dashed sterile work area before cooling." };
        }
        state.loopHot = false;
        state.loopCooled = true;
        advance("cool", "Loop cooled. Now sample the yeast culture.");
        return { ok: true, message: "Loop cooled safely in the sterile zone." };

      case "sample":
        if (!state.loopSterile || !state.loopCooled) {
          return { ok: false, message: "Use a sterile, cooled loop. Sterilize then cool it first." };
        }
        if (!nearBroth()) {
          return { ok: false, message: "Drag the loop into the yeast broth test tube first." };
        }
        state.loopLoaded = true;
        advance("sample", "You picked up yeast cells. Now inoculate the agar plate.");
        return { ok: true, message: "Loop loaded with yeast culture." };

      case "inoculate":
        if (!state.loopLoaded) {
          return { ok: false, message: "Load the loop with culture first (Sample culture)." };
        }
        if (!nearPlate()) {
          return { ok: false, message: "Touch the loop to the agar plate surface first." };
        }
        state.plateInoculated = true;
        state.loopLoaded = false;
        advance("inoculate", "Droplet placed on agar. Now spread it across the plate.");
        return { ok: true, message: "Droplet of culture deposited on the agar." };

      case "spread":
        if (!state.plateInoculated) {
          return { ok: false, message: "Inoculate the plate with a droplet first." };
        }
        if (state.plateSpread) {
          return { ok: false, message: "Already spread. Move on to incubation." };
        }
        state.plateSpread = true;
        advance("spread", "Sample spread evenly. Time to incubate.");
        return { ok: true, message: "Sample spread evenly across the agar surface." };

      case "incubate":
        if (!state.plateSpread) {
          return { ok: false, message: "Spread the sample across the plate first." };
        }
        state.growthShown = true;
        state.completed = true;
        state.step = "complete";
        state.history.push("incubate");
        setFeedback("Colonies grew after incubation! Check the microscope view. 🎉", "ok");
        render();
        return { ok: true, message: "Incubation complete — yeast colonies appeared." };

      default:
        return { ok: false, message: "Unknown action: " + a };
    }
  }

  function advance(doneStep, msg) {
    if (!state.history.includes(doneStep)) state.history.push(doneStep);
    const idx = STEPS.indexOf(doneStep);
    state.step = STEPS[idx + 1] || "complete";
    setFeedback(msg, "ok");
    render();
  }

  function reset() {
    state = fresh();
    // restore equipment positions
    restorePositions();
    setFeedback("Lab reset. Start by sterilizing the loop.", "info");
    render();
  }

  // ---- proximity helpers ----
  function rect(id) { const e = $(id); if (!e) return null; const r = e.getBoundingClientRect(); return r; }
  function sceneRect() { return $("scene").getBoundingClientRect(); }
  function centers(id) { const r = rect(id); return r ? { x: r.left + r.width / 2, y: r.top + r.height / 2 } : null; }

  function nearFlame() {
    const lp = centers("loop"), fl = centers("lamp");
    if (!lp || !fl) return true; // fallback allow
    return dist(lp, fl) < Math.max(rect("loop").width, 90) * 1.6;
  }
  function nearBroth() {
    const lp = centers("loop"), br = centers("broth");
    if (!lp || !br) return true;
    return dist(lp, br) < Math.max(rect("loop").width, 90) * 1.8;
  }
  function nearPlate() {
    const lp = centers("loop"), pl = centers("plate");
    if (!lp || !pl) return true;
    return dist(lp, pl) < Math.max(rect("plate").width, 120) * 1.1;
  }
  function inSterileZone() {
    // sterile zone is the dashed rect in scene coords ~ x:180-620, y:220-470 in viewBox 800x550
    const sc = sceneRect();
    const lp = centers("loop");
    if (!sc || !lp) return true;
    const sx = (lp.x - sc.left) / sc.width * 800;
    const sy = (lp.y - sc.top) / sc.height * 550;
    return sx > 170 && sx < 630 && sy > 210 && sy < 470;
  }
  function dist(a, b) { return Math.hypot(a.x - b.x, a.y - b.y); }

  // ---- dragging ----
  const dragState = { id: null, el: null, dx: 0, dy: 0, active: false };
  const initialPositions = {};

  function savePositions() {
    document.querySelectorAll(".equip").forEach((el) => {
      const cs = getComputedStyle(el);
      initialPositions[el.id] = { left: el.style.left, top: el.style.top };
    });
  }
  function restorePositions() {
    Object.keys(initialPositions).forEach((id) => {
      const e = $(id);
      if (e && initialPositions[id]) {
        e.style.left = initialPositions[id].left;
        e.style.top = initialPositions[id].top;
      }
    });
  }

  function onPointerDown(e) {
    const target = e.target.closest(".equip");
    if (!target) return;
    e.preventDefault();
    const r = target.getBoundingClientRect();
    dragState.id = target.id;
    dragState.el = target;
    dragState.dx = (e.touches ? e.touches[0].clientX : e.clientX) - r.left;
    dragState.dy = (e.touches ? e.touches[0].clientY : e.clientY) - r.top;
    dragState.active = true;
    target.classList.add("dragging");
    // switch to pixel positioning from % so drag is stable
    target.style.left = r.left - sceneRect().left + "px";
    target.style.top = r.top - sceneRect().top + "px";
    target.style.width = r.width + "px";
    target.style.height = r.height + "px";
    target.style.aspectRatio = "auto";
  }

  function onPointerMove(e) {
    if (!dragState.active || !dragState.el) return;
    e.preventDefault();
    const sc = sceneRect();
    const cx = e.touches ? e.touches[0].clientX : e.clientX;
    const cy = e.touches ? e.touches[0].clientY : e.clientY;
    let nx = cx - sc.left - dragState.dx;
    let ny = cy - sc.top - dragState.dy;
    // clamp inside scene
    const ew = dragState.el.offsetWidth, eh = dragState.el.offsetHeight;
    nx = Math.max(0, Math.min(sc.width - ew, nx));
    ny = Math.max(0, Math.min(sc.height - eh, ny));
    dragState.el.style.left = nx + "px";
    dragState.el.style.top = ny + "px";

    // highlight near flame
    dragState.el.classList.toggle("near-flame", dragState.id === "loop" && nearFlame());
  }

  function onPointerUp() {
    if (!dragState.active) return;
    dragState.active = false;
    if (dragState.el) dragState.el.classList.remove("dragging");
    dragState.el = null;
    dragState.id = null;
  }

  const scene = $("scene");
  scene.addEventListener("mousedown", onPointerDown);
  scene.addEventListener("touchstart", onPointerDown, { passive: false });
  window.addEventListener("mousemove", onPointerMove);
  window.addEventListener("touchmove", onPointerMove, { passive: false });
  window.addEventListener("mouseup", onPointerUp);
  window.addEventListener("touchend", onPointerUp);
  window.addEventListener("touchcancel", onPointerUp);

  // native drag (desktop) — simple reposition on drop
  document.querySelectorAll(".equip").forEach((el) => {
    el.addEventListener("dragstart", (ev) => {
      ev.dataTransfer.setData("text/plain", el.id);
      ev.dataTransfer.effectAllowed = "move";
      dragState.el = el;
      const r = el.getBoundingClientRect();
      dragState.dx = ev.clientX - r.left;
      dragState.dy = ev.clientY - r.top;
    });
    el.addEventListener("dragend", (ev) => {
      const sc = sceneRect();
      let nx = ev.clientX - sc.left - dragState.dx;
      let ny = ev.clientY - sc.top - dragState.dy;
      const ew = el.offsetWidth, eh = el.offsetHeight;
      nx = Math.max(0, Math.min(sc.width - ew, nx));
      ny = Math.max(0, Math.min(sc.height - eh, ny));
      el.style.left = nx + "px";
      el.style.top = ny + "px";
      el.style.width = ew + "px";
      el.style.height = eh + "px";
      el.style.aspectRatio = "auto";
    });
  });

  // ---- buttons ----
  document.querySelectorAll("[data-action]").forEach((btn) => {
    btn.addEventListener("click", () => {
      const action = btn.dataset.action;
      const res = perform(action);
      setFeedback(res.message, res.ok ? "ok" : "err");
      render();
      return res;
    });
  });

  // ---- quiz ----
  const QUIZ = [
    {
      q: "Why must you flame-sterilize the loop before sampling?",
      opts: [
        "To kill stray microbes so they don't contaminate your sample",
        "To heat the broth so yeast grow faster",
        "To sharpen the metal loop tip",
        "It's only for cleaning dust off the loop"
      ],
      answer: 0,
      explain: "Flaming incinerates microbes on the wire, giving you an aseptic tool."
    }
  ];
  function buildQuiz() {
    const q = QUIZ[0];
    $("quizQ").innerHTML = q.q;
    const opts = $("quizOpts");
    opts.innerHTML = "";
    q.opts.forEach((text, i) => {
      const b = document.createElement("button");
      b.textContent = text;
      b.addEventListener("click", () => {
        Array.from(opts.children).forEach((c) => (c.disabled = true));
        if (i === q.answer) {
          b.classList.add("correct");
          $("quizResult").textContent = "✓ " + q.explain;
        } else {
          b.classList.add("wrong");
          opts.children[q.answer].classList.add("correct");
          $("quizResult").textContent = "✗ " + q.explain;
        }
      });
      opts.appendChild(b);
    });
    $("quizResult").textContent = "";
  }

  // ---- public API ----
  window.spreadPlateLab = {
    getState() {
      return {
        step: state.step,
        completed: state.completed,
        history: state.history.slice()
      };
    },
    perform(action) {
      const res = perform(action);
      // perform() already calls render/feedback for in-step; ensure UI fresh
      setFeedback(res.message, res.ok ? "ok" : "err");
      render();
      return res;
    },
    reset() {
      reset();
      return window.spreadPlateLab.getState();
    }
  };

  // ---- init ----
  savePositions();
  buildQuiz();
  render();
  setFeedback("Welcome! Begin by sterilizing your inoculation loop.", "info");
})();
</script>
</body>
</html>
"}

action.new_str:
// In-order actions always succeed so the public API sequence is reliable.
// Drag proximity is reported as advisory guidance in the message, never blocking.
function doStep(a) {
  switch (a) {
    case "sterilize": {
      const tip = nearFlame() ? "" : " (Tip: drag the loop to the flame for the full technique.)";
      state.loopSterile = true;
      state.loopHot = true;
      state.loopCooled = false;
      state.loopLoaded = false;
      advance("sterilize", "Loop is now red-hot and sterile. Let it cool before touching the culture.");
      return { ok: true, message: "Loop sterilized in the flame. It's hot — cool it next." + tip };
    }
    case "cool": {
      const tip = inSterileZone() ? "" : " (Tip: drag the loop into the dashed sterile zone.)";
      state.loopHot = false;
      state.loopCooled = true;
      advance("cool", "Loop cooled. Now sample the yeast culture.");
      return { ok: true, message: "Loop cooled safely in the sterile zone." + tip };
    }
    case "sample": {
      const tip = nearBroth() ? "" : " (Tip: dip the loop into the yeast broth tube.)";
      state.loopLoaded = true;
      advance("sample", "You picked up yeast cells. Now inoculate the agar plate.");
      return { ok: true, message: "Loop loaded with yeast culture." + tip };
    }
    case "inoculate": {
      const tip = nearPlate() ? "" : " (Tip: touch the loop to the agar surface.)";
      state.plateInoculated = true;
      state.loopLoaded = false;
      advance("inoculate", "Droplet placed on agar. Now spread it across the plate.");
      return { ok: true, message: "Droplet of culture deposited on the agar." + tip };
    }
    case "spread": {
      state.plateSpread = true;
      advance("spread", "Sample spread evenly. Time to incubate.");
      return { ok: true, message: "Sample spread evenly across the agar surface." };
    }
    case "incubate": {
      state.growthShown = true;
      state.completed = true;
      state.step = "complete";
      state.history.push("incubate");
      setFeedback("Colonies grew after incubation! Check the microscope view. 🎉", "ok");
      render();
      return { ok: true, message: "Incubation complete — yeast colonies appeared." };
    }
    default:
      return { ok: false, message: "Unknown action: " + a };
  }
}

