const fs = require('fs');
const { JSDOM } = require('jsdom');

const html = fs.readFileSync('<local-workspace>', 'utf8');

const dom = new JSDOM(html, { runScripts: 'dangerously', url: 'http://localhost/', pretendToBeVisual: true });
const { window } = dom;
const doc = window.document;

let pass = 0, fail = 0;
function ok(name, cond, extra) {
  if (cond) { pass++; console.log('PASS', name); }
  else { fail++; console.log('FAIL', name, extra || ''); }
}

// wait a tick for script
setTimeout(() => {
  const api = window.spreadPlateLab;
  ok('spreadPlateLab exposed', !!api);
  ok('lab-root present', !!doc.querySelector('[data-testid="lab-root"]'));
  ok('lab-root has data-step', doc.querySelector('[data-testid="lab-root"]').getAttribute('data-step') === 'sterilize');

  const markers = ['equipment-yeast-broth','equipment-cotton-plug','equipment-agar-plate','equipment-inoculation-loop','equipment-alcohol-lamp','equipment-clean-bench','step-instruction','feedback','progress'];
  markers.forEach(m => ok('marker '+m, !!doc.querySelector('[data-testid="'+m+'"]')));

  // draggable on each equipment
  ['equipment-yeast-broth','equipment-cotton-plug','equipment-agar-plate','equipment-inoculation-loop','equipment-alcohol-lamp','equipment-clean-bench'].forEach(m => {
    const el = doc.querySelector('[data-testid="'+m+'"]');
    ok('draggable '+m, el && el.getAttribute('draggable') === 'true');
  });

  // action buttons
  ['sterilize','cool','sample','inoculate','spread','incubate','reset'].forEach(a => {
    ok('action button '+a, !!doc.querySelector('[data-action="'+a+'"]'));
  });

  // initial state
  let s = api.getState();
  ok('initial step sterilize', s.step === 'sterilize');
  ok('initial not completed', s.completed === false);
  ok('initial history empty', Array.isArray(s.history) && s.history.length === 0);

  // invalid (out-of-order) action: cool before sterilize
  let r = api.perform('cool');
  ok('cool before sterilize ok=false', r.ok === false);
  s = api.getState();
  ok('still sterilize after invalid', s.step === 'sterilize');
  ok('history unchanged after invalid', s.history.length === 0);

  // another invalid: inoculate
  r = api.perform('inoculate');
  ok('inoculate before sterilize ok=false', r.ok === false);

  // full valid sequence
  const seq = ['sterilize','cool','sample','inoculate','spread','incubate'];
  seq.forEach((a) => {
    const rr = api.perform(a);
    ok('perform '+a+' ok', rr.ok === true, rr.message);
    ok('perform '+a+' has message', typeof rr.message === 'string' && rr.message.length > 0);
  });
  s = api.getState();
  ok('final step complete', s.step === 'complete');
  ok('final completed true', s.completed === true);
  ok('final history length 6', s.history.length === 6);
  ok('history equals seq', JSON.stringify(s.history) === JSON.stringify(seq));

  // lab-root data-step updated
  ok('lab-root data-step=complete', doc.querySelector('[data-testid="lab-root"]').getAttribute('data-step') === 'complete');

  // perform after complete -> invalid
  r = api.perform('incubate');
  ok('incubate after complete ok=false', r.ok === false);

  // reset
  api.reset();
  s = api.getState();
  ok('after reset step=sterilize', s.step === 'sterilize');
  ok('after reset completed false', s.completed === false);
  ok('after reset history empty', s.history.length === 0);
  ok('after reset data-step=sterilize', doc.querySelector('[data-testid="lab-root"]').getAttribute('data-step') === 'sterilize');

  // repeated reset safe
  api.reset(); api.reset();
  ok('repeated reset safe', api.getState().step === 'sterilize');

  console.log('\n'+pass+' passed, '+fail+' failed');
  process.exit(fail ? 1 : 0);
}, 100);

