cd /tmp/jsdom-test && cat > phone.js <<'EOF'
const fs = require('fs');
const { JSDOM } = require('jsdom');
const html = fs.readFileSync('<local-workspace>','utf8');
const dom = new JSDOM(html, { runScripts:'dangerously', url:'http://localhost/', pretendToBeVisual:true, resources:'usable' });
const { window } = dom;
const errs = [];
window.addEventListener('error', e => errs.push(e.message));
window.addEventListener('unhandledrejection', e => errs.push('rej:'+(e&&e.reason)));
// simulate phone width
Object.defineProperty(window, 'innerWidth', { value: 390, configurable: true });
Object.defineProperty(window, 'innerHeight', { value: 780, configurable: true });
setTimeout(() => {
  // fire resize
  window.dispatchEvent(new window.Event('resize'));
  // try clicking an action button and a reset
  const btn = window.document.querySelector('[data-action="cool"]');
  btn && btn.dispatchEvent(new window.Event('click'));
  const reset = window.document.querySelector('[data-action="reset"]');
  reset && reset.dispatchEvent(new window.Event('click'));
  setTimeout(() => {
    console.log('errors:', errs.length ? errs : 'none');
    console.log('state after reset:', JSON.stringify(window.spreadPlateLab.getState()));
    process.exit(0);
  }, 50);
}, 100);
EOF
